<?php require_once __DIR__.'/config/app.php';
$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();
if($count>0){exit('Admin sudah dibuat. Hapus file setup_admin.php dari folder proyek demi keamanan.');}
$err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$pass=$_POST['password']??'';if(!$name||!$email||!$phone||strlen($pass)<8)$err='Lengkapi data. Password minimal 8 karakter.';else{$s=$pdo->prepare("INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?, 'admin')");$s->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);echo 'Admin berhasil dibuat. Hapus file setup_admin.php sekarang, lalu login.';exit;}}
